// Leads tab: Lead ID, Name, Phone, Interested in, Last contact (yyyy-mm-dd), Notes, Status (open / won / lost / stop), Followups
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.Phone || !r['Last contact']) continue;
  const day = Math.round($now.setZone('Asia/Kolkata').startOf('day').diff(DateTime.fromISO(r['Last contact'], { zone: 'Asia/Kolkata' }).startOf('day'), 'days').days);
  const done = String(r.Followups || '').split(',').map(s => s.trim()).filter(Boolean);
  if ([1, 3, 7].includes(day) && !done.includes(String(day))) out.push({ json: { ...r, day, Followups: [...done, String(day)].join(',') } });
}
return out;

